//! The generated Markdown report.
//!
//! It renders the result document and nothing else: no commentary the JSON does
//! not support, and no aggregate score. The matrix is scenario × target, so a
//! target that holds one line and loses another cannot average them away.

use std::fmt::Write;

use crate::result::{BenchResult, RunResult, Status};

pub fn render(result: &BenchResult) -> String {
    let mut out = String::new();
    let _ = writeln!(out, "# MCP governance smoke pack — results\n");
    let _ = writeln!(
        out,
        "Generated by `govbench` from `{}`. Result schema v{}.\n",
        result.pack.path, result.v
    );
    let _ = writeln!(
        out,
        "World `{}` (manifest `{}`).\n",
        result.pack.world_id,
        short(&result.pack.manifest_hash)
    );

    let _ = writeln!(out, "## Targets\n");
    for target in &result.targets {
        let _ = writeln!(out, "- **`{}`** — {}", target.id, target.description);
    }
    let _ = writeln!(out);

    let _ = writeln!(out, "## Per-scenario results\n");
    let _ = writeln!(
        out,
        "Each cell is one scenario's verdict for one target, plus the number of \
         downstream effects the runner observed. There is no aggregate score.\n"
    );
    let targets: Vec<&str> = result.targets.iter().map(|t| t.id.as_str()).collect();
    let _ = write!(out, "| Scenario |");
    for target in &targets {
        let _ = write!(out, " `{target}` |");
    }
    let _ = writeln!(out);
    let _ = write!(out, "|---|");
    for _ in &targets {
        let _ = write!(out, "---|");
    }
    let _ = writeln!(out);
    for scenario in &result.pack.scenarios {
        let _ = write!(out, "| `{scenario}` |");
        for target in &targets {
            match find(result, scenario, target) {
                Some(run) => {
                    let _ = write!(
                        out,
                        " {} ({} effect{}) |",
                        run.outcome.as_str(),
                        run.effect_count,
                        if run.effect_count == 1 { "" } else { "s" }
                    );
                }
                None => {
                    let _ = write!(out, " — |");
                }
            }
        }
        let _ = writeln!(out);
    }
    let _ = writeln!(out);

    if let Some(parity) = &result.transport_parity {
        let _ = writeln!(out, "## Transport parity\n");
        let _ = writeln!(out, "**{}** — {}\n", parity.status.as_str(), parity.detail);
    }

    let _ = writeln!(out, "## Evidence\n");
    for scenario in &result.pack.scenarios {
        let Some(first) = result.runs.iter().find(|run| &run.scenario == scenario) else {
            continue;
        };
        let _ = writeln!(out, "### `{}` — {}\n", first.scenario, first.title.trim());
        let _ = writeln!(out, "> {}\n", first.question.trim());
        for run in result.runs.iter().filter(|run| &run.scenario == scenario) {
            let _ = writeln!(
                out,
                "#### `{}` → **{}**, {} downstream effect(s)\n",
                run.target,
                run.outcome.as_str(),
                run.effect_count
            );
            let _ = writeln!(out, "| Step | Principal | Verdict | Rule | Effect |");
            let _ = writeln!(out, "|---|---|---|---|---|");
            for step in &run.steps {
                let _ = writeln!(
                    out,
                    "| `{}` ({}) | `{}` via `{}` | {} | {} | {} |",
                    step.id,
                    step.op,
                    step.principal_id,
                    step.channel,
                    step.verdict.as_str(),
                    step.rule.as_deref().unwrap_or("—"),
                    if step.effect_applied {
                        "**applied**"
                    } else {
                        "none"
                    }
                );
            }
            let _ = writeln!(out);
            let _ = writeln!(out, "| Check | Result | Detail |");
            let _ = writeln!(out, "|---|---|---|");
            for check in &run.checks {
                let _ = writeln!(
                    out,
                    "| `{}` | {} | {} |",
                    check.id,
                    check.status.as_str(),
                    check.detail.replace('|', "\\|")
                );
            }
            let _ = writeln!(out);
        }
    }

    let failures: Vec<&RunResult> = result
        .runs
        .iter()
        .filter(|run| run.outcome == Status::Fail)
        .collect();
    let _ = writeln!(out, "## Failing runs\n");
    if failures.is_empty() {
        let _ = writeln!(out, "None.\n");
    } else {
        for run in failures {
            for check in run.checks.iter().filter(|c| c.status == Status::Fail) {
                let _ = writeln!(
                    out,
                    "- `{}` / `{}` — **{}**: {}",
                    run.target, run.scenario, check.id, check.detail
                );
            }
        }
        let _ = writeln!(out);
    }
    out
}

fn find<'a>(result: &'a BenchResult, scenario: &str, target: &str) -> Option<&'a RunResult> {
    result
        .runs
        .iter()
        .find(|run| run.scenario == scenario && run.target == target)
}

fn short(hash: &str) -> String {
    hash.chars().take(12).collect()
}
